facilityFormItem.valueChangedEventHandler:
functions.removeError(window.errorShiftPeriod);
functions.addPerformingAction('ChangeInitiator');
var initiatorId = formItem.value || functions.getValues().Initiator;
if (initiatorId != null) {
  ESS.network.sendRequest(`/api/functions/GetInstructionWithLinkLNA?employeeId=${initiatorId}`)
  .then(function (instruction) {
    if (typeof instruction === "string") {
      if (instruction) {
        functions.setValue('Instruction', instruction);
      }
    }
  });
  functions.removeError(window.errorInitiator);
  ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned?employeeId=${initiatorId}`)
  .then(function (isConsentSigned) {
    if (isConsentSigned != true) {
      functions.setDataSource('ShiftPeriod', `/api/functions/GetJsonForDataSource`);
      window.errorInitiator = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'));
      functions.removePerformingAction();
    } else {
      ESS.network.sendRequest(`/api/functions/GetVacationDataForShiftByStatement?employeeId=${initiatorId}`)
      .then(function (vacationData) {
        functions.setValue('AvailableVacationData', JSON.stringify(vacationData));
        var shiftKind = functions.getValues().ShiftKind;
        if (shiftKind) {
          if (shiftKind == 1) {
            vacationData = vacationData.filter(item => item.IsPlanned);
          } else {
            vacationData = vacationData.filter(item => !item.IsPlanned);
          }
          functions.setDataSource('ShiftPeriod', `/api/functions/GetJsonForDataSource?json=${JSON.stringify(vacationData)}`);
          if (!vacationData.length) {
            window.errorShiftPeriod = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSHIFTVACATIONBYSTATEMENT_SHIFTPERIOD_ERROR'), undefined, ESS.enums.FormErrorType.SYSTEM, 'ShiftPeriod');
          }
        }
        functions.removePerformingAction();
      });
    }
    window.clearRowsInfo();
  })
  .catch(function (error) {
    functions.removePerformingAction();
    ESS.toasts.showToast(error.message, 'danger', false);
  });
}

window.clearRowsInfo();
var availableVacationData = JSON.parse(functions.getValues().AvailableVacationData);
functions.removeError(window.errorShiftPeriod);
if (formItem.value == 1) {
  availableVacationData = availableVacationData.filter(item => item.IsPlanned);
} else {
  availableVacationData = availableVacationData.filter(item => !item.IsPlanned);
}
var shiftPeriods = availableVacationData.map((item) => ({ ["Number"]: item.Number, ["VacationPeriod"]: item.VacationPeriod }));
functions.setDataSource('ShiftPeriod', `/api/functions/GetJsonForDataSource?json=${JSON.stringify(shiftPeriods)}`);
if (!shiftPeriods.length) {
  window.errorShiftPeriod = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_NNSHIFTVACATIONBYSTATEMENT_SHIFTPERIOD_ERROR'), undefined, ESS.enums.FormErrorType.SYSTEM, 'ShiftPeriod');
}

if (formItem.value) {
  var availableVacationData = JSON.parse(functions.getValues().AvailableVacationData);
  var shiftPeriod = availableVacationData.find(item => item.Number == formItem.value);
  functions.setValue('ShiftPeriodJson', JSON.stringify(shiftPeriod));
  functions.setValue('VacationsJson', JSON.stringify(shiftPeriod.Vacations));
  functions.setValue('ShiftPeriodInfo', shiftPeriod.VacationPeriodInfo);
  var types = shiftPeriod.Vacations.map(x => x.Type);
  functions.setDataSource('VacationType', `/api/functions/GetVacationTypesForShiftByStatement?types=${types}`);
} else {
  functions.setValue('ShiftPeriodInfo', '');
  functions.setDataSource('VacationType', `/api/functions/GetVacationTypesForShiftByStatement?types=[]`);
}

